## 🧩 3. Código JavaScript (`script.js`)

Este script é minimalista, focado em adicionar uma funcionalidade de smooth scrolling (rolagem suave) e um leve toque de animação ao carregar a página, o que adiciona um toque de "coolness" moderno.

```javascript
document.addEventListener('DOMContentLoaded', function() {
    console.log("🤖 Summarify AI Landing Page carregada com sucesso! Pronto para converter.");

    // 1. Smooth Scrolling para links âncora
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            e.preventDefault();
            document.querySelector(this.getAttribute('href')).scrollIntoView({
                behavior: 'smooth'
            });
        });
    });

    // 2. Adicionar uma classe de animação suave ao corpo da página (Opcional: para um efeito "fade-in" no carregamento)
    document.body.style.opacity = 0;
    setTimeout(() => {
        document.body.style.transition = 'opacity 1s ease-out';
        document.body.style.opacity = 1;
    }, 50); // Pequeno atraso para o efeito de entrada

    // 3. Simulação de animação de cards ao aparecer (Se você quiser usar uma biblioteca como AOS - Animate On Scroll)
    // Por simplicidade, este exemplo foca no básico, mas esta é a função de onde você adicionaria rotas de animação.
    const featureCards = document.querySelectorAll('.feature-card');

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.style.opacity = 1;
                entry.target.style.transform = 'translateY(0)';
                observer.unobserve(entry.target);
            }
        });
    }, { threshold: 0.1 }); // Aciona quando 10% do elemento está visível

    featureCards.forEach(card => {
        card.style.opacity = 0;
        card.style.transform = 'translateY(20px)';
        card.style.transition = 'opacity 0.6s ease-out, transform 0.6s ease-out';
        observer.observe(card);
    });

});
```

